package codec

import (
	"encoding/binary"
	"errors"
	"fmt"
	"hash/crc32"
	"io"
	"os"
	"path/filepath"
	"sync"
)

// Reliable transport on top of the multi-frame Session.
//
// This layer adds sequence numbers, cumulative acknowledgements and a
// sliding-window pipeline. It does not touch the wire encoding of the
// layer below: every reliable message is carried inside the Payload of
// one ordinary codec frame, prefixed by this layer's own 20-byte
// envelope. Encode/Decode, the header constants and the four existing
// error values keep their exact byte-level semantics.
//
// Envelope layout inside a frame payload (all multi-byte fields
// big-endian):
//
//	+---------+---------+--------+----------+----------+=========+
//	| seq (4) | ack (4) | type(1)| flags(2) | crc32(4) | payload |
//	+---------+---------+--------+----------+----------+=========+
//
// seq is the sender-assigned frame sequence (data frames; ACK frames
// repeat the sender's own next data seq), ack is the highest
// contiguously-delivered sequence on the receiver (cumulative), and the
// trailing CRC32 (IEEE) covers the 16 envelope bytes before it plus the
// payload. The per-frame payload limit is still MaxPayload, measured on
// the inner payload: EnvelopeSize is reserved for the envelope.
//
// Delivery guarantees, across disconnects and process restarts:
//   - Write side: frames are numbered in write order and streamed
//     through a fixed send window. Written frames are journaled to a
//     replay log; the last acknowledged position is checkpointed. After
//     a restart, sending resumes strictly after the last acknowledged
//     frame, so acknowledged frames are never resent.
//   - Read side: frames are delivered in sequence order exactly once.
//     Duplicates of already-delivered frames (a resend after a lost
//     acknowledgement) are acknowledged again but delivered once; frames
//     arriving ahead of order but inside the window are held and
//     delivered once the gap closes; frames older than the window or
//     whose declared sequence lies beyond the window width are refused,
//     and delivery stops at the current delivered position.
const (
	// EnvelopeSize is this layer's per-frame overhead:
	// 4 (seq) + 4 (ack) + 1 (type) + 2 (flags) + 4 (crc32).
	EnvelopeSize = 15

	// ReliableMaxPayload is the largest inner payload a reliable data
	// frame may carry; EnvelopeSize bytes are reserved inside the
	// underlying frame, whose own limit stays MaxPayload.
	ReliableMaxPayload = MaxPayload - EnvelopeSize

	// envelope field offsets.
	envSeqOff   = 0
	envAckOff   = 4
	envTypeOff  = 8
	envFlagsOff = 9
	envCRCOff   = 11
	envBodyOff  = 15
)

const (
	envTypeData = 1
	envTypeAck  = 2
)

// ErrWindowFull is the established over-limit value a write returns when
// the send window already holds the maximum number of unacknowledged
// frames. It is the same sentinel the single-frame encoder uses for an
// over-limit payload: an over-window write is an over-limit write, and
// the offered frame is dropped without entering the window or the log.
var ErrWindowFull = ErrTooLarge

// ReliableFrame is one caller-visible frame on the reliable layer.
type ReliableFrame struct {
	Flags   uint16
	Kind    uint8
	Payload []byte
}

// envelope is one parsed reliable message.
type envelope struct {
	seq     uint32
	ack     uint32
	typ     uint8
	flags   uint16
	payload []byte
}

// encodeEnvelope serializes one message into the payload bytes of an
// ordinary codec frame.
func encodeEnvelope(e envelope) ([]byte, error) {
	if e.typ == envTypeData && len(e.payload) > ReliableMaxPayload {
		return nil, ErrTooLarge
	}
	out := make([]byte, EnvelopeSize+len(e.payload))
	binary.BigEndian.PutUint32(out[envSeqOff:envSeqOff+4], e.seq)
	binary.BigEndian.PutUint32(out[envAckOff:envAckOff+4], e.ack)
	out[envTypeOff] = e.typ
	binary.BigEndian.PutUint16(out[envFlagsOff:envFlagsOff+2], e.flags)
	copy(out[envBodyOff:], e.payload)
	// CRC over the whole message except the CRC field itself.
	sum := crc32.ChecksumIEEE(out[:envCRCOff])
	// crc32 has no rolling-with-tail API here; checksum body together
	// with the header bytes by writing both into one hash.
	h := crc32.NewIEEE()
	h.Write(out[:envCRCOff])
	h.Write(out[envBodyOff:])
	sum = h.Sum32()
	binary.BigEndian.PutUint32(out[envCRCOff:envCRCOff+4], sum)
	return out, nil
}

// decodeEnvelope parses one message from a codec frame payload. A
// damaged envelope is reported with the established checksum value;
// nothing is delivered from it.
func decodeEnvelope(p []byte) (envelope, error) {
	var e envelope
	if len(p) < EnvelopeSize {
		return e, ErrShortFrame
	}
	h := crc32.NewIEEE()
	h.Write(p[:envCRCOff])
	h.Write(p[envBodyOff:])
	if h.Sum32() != binary.BigEndian.Uint32(p[envCRCOff:envCRCOff+4]) {
		return e, ErrChecksum
	}
	e.seq = binary.BigEndian.Uint32(p[envSeqOff : envSeqOff+4])
	e.ack = binary.BigEndian.Uint32(p[envAckOff : envAckOff+4])
	e.typ = p[envTypeOff]
	e.flags = binary.BigEndian.Uint16(p[envFlagsOff : envFlagsOff+2])
	body := make([]byte, len(p)-EnvelopeSize)
	copy(body, p[EnvelopeSize:])
	e.payload = body
	return e, nil
}

// toFrame wraps an envelope in a codec frame of the given Kind. Data
// carries the caller's Kind in the reliable flags/kind; the outer codec
// Kind uses an internal marker so the peer can tell directions apart
// even before decoding the payload.
func encodeReliableFrame(e envelope, kind uint8) (Frame, error) {
	b, err := encodeEnvelope(e)
	if err != nil {
		return Frame{}, err
	}
	return Frame{Flags: 0, Kind: kind, Payload: b}, nil
}

// ReliableConfig configures a ReliableSession. The zero value is not
// usable: StateDir must be set so write state survives a restart.
type ReliableConfig struct {
	// Window is the send/receive window width in frames. It must be
	// positive. Both peers of one connection should use the same width.
	Window int

	// StateDir holds the checkpoint file and replay log used to resume
	// the write side after a restart. It is created if missing.
	StateDir string
}

// ReliableSession is a reliability layer wrapping one Session. Create it
// with NewReliable; the wrapped session must not be used directly while
// the ReliableSession owns it.
type ReliableSession struct {
	sess *Session
	cfg  ReliableConfig

	wmu sync.Mutex
	// sendBase is the oldest sequence not yet acknowledged; sendNext is
	// the next sequence to number a newly written frame. Window slots:
	// [sendBase, sendBase+Window); a slot holds the frame bytes until the
	// cumulative ack passes it.
	sendBase uint32
	sendNext uint32
	window   []windowSlot
	log      *replayLog
	closed   bool

	rmu sync.Mutex
	// recvBase is the next sequence expected/delivered. held stores
	// in-window frames that arrived ahead of order. delivered marks
	// sequences at or below recvBase-1 conceptually; the bitmap only
	// needs to cover the current window for duplicate detection.
	recvBase uint32
	held     map[uint32]ReliableFrame
	rerr     error
}

type windowSlot struct {
	used bool
	seq  uint32
	kind uint8
	f    ReliableFrame
}

// NewReliable wraps sess in a reliable session. Write state (checkpoint
// and replay log) is read from cfg.StateDir when present: a fresh
// directory starts at sequence 0, while a directory left by a crashed
// process resumes after the last fully acknowledged position. An
// unfinished checkpoint is detected and discarded in favor of the
// previous complete one.
func NewReliable(sess *Session, cfg ReliableConfig) (*ReliableSession, error) {
	if cfg.Window <= 0 {
		return nil, errors.New("codec: reliable window must be positive")
	}
	if cfg.StateDir == "" {
		return nil, errors.New("codec: reliable session requires a state directory")
	}
	if err := os.MkdirAll(cfg.StateDir, 0o755); err != nil {
		return nil, err
	}

	rs := &ReliableSession{
		sess:   sess,
		cfg:    cfg,
		window: make([]windowSlot, cfg.Window),
		held:   make(map[uint32]ReliableFrame),
	}

	// Load the newest complete checkpoint; a half-written record is
	// rejected by its checksum and the previous record is used instead.
	acked, haveCP, err := loadCheckpoint(cfg.StateDir)
	if err != nil {
		return nil, err
	}

	rs.log, err = openReplayLog(cfg.StateDir)
	if err != nil {
		return nil, err
	}

	if haveCP {
		// Reconcile checkpoint and replay log: resume from the EARLIER of
		// the two acknowledged/complete positions. Frames before that
		// point are known delivered; frames from that point on are
		// replayed from the log if still present. A log gap (frames
		// already discarded after a later checkpoint) simply means
		// nothing is left to resend.
		logBase, logNext, err := rs.log.bounds()
		if err != nil {
			return nil, err
		}
		base := acked + 1
		// If the log does not reach back to base, the checkpointed
		// position is the authoritative floor: clamp base up only to data
		// the log can actually supply, but never above the checkpointed
		// resume point when the log claims a later base that the
		// checkpoint does not know about.
		switch {
		case logNext <= base:
			// Log contains nothing the peer has not already acknowledged.
			rs.sendBase = base
			rs.sendNext = base
		case logBase > base:
			// Position disagreement with an un-replayable gap: take the
			// earlier confirmed position as the resume point, but the
			// missing frames are gone, so the window must start at the
			// first frame the log can replay. No frame in the overlap is
			// skipped: the receiver dedupes anything it already got.
			rs.sendBase = logBase
			rs.sendNext = maxU32(logNext, base)
		default:
			rs.sendBase = base
			rs.sendNext = logNext
		}
		rs.reloadWindow()
	}

	return rs, nil
}

func maxU32(a, b uint32) uint32 {
	if a > b {
		return a
	}
	return b
}

// reloadWindow refills the in-memory window slots from the replay log
// after a restart, so an immediate Flush resends everything not yet
// acknowledged.
func (rs *ReliableSession) reloadWindow() {
	for i := range rs.window {
		rs.window[i] = windowSlot{}
	}
	frames := rs.log.framesFrom(rs.sendBase)
	for _, fr := range frames {
		idx := int(fr.seq - rs.sendBase)
		if idx >= len(rs.window) {
			break
		}
		rs.window[idx] = windowSlot{
			used: true,
			seq:  fr.seq,
			kind: fr.kind,
			f:    fr.f,
		}
	}
}

// WriteFrame numbers f with the next send sequence, journals it and
// places it in the send window. The frame is not transmitted until
// Flush. If the window already holds the maximum number of
// unacknowledged frames, WriteFrame returns ErrWindowFull (the
// established over-limit value) and drops the frame: it is neither
// windowed nor journaled, so its sequence number is not consumed.
func (rs *ReliableSession) WriteFrame(f ReliableFrame) error {
	if len(f.Payload) > ReliableMaxPayload {
		return ErrTooLarge
	}
	rs.wmu.Lock()
	defer rs.wmu.Unlock()

	if rs.closed {
		return errors.New("codec: write on closed reliable session")
	}

	outstanding := rs.sendNext - rs.sendBase
	if outstanding >= uint32(rs.cfg.Window) {
		return ErrWindowFull
	}

	seq := rs.sendNext
	if err := rs.log.append(seq, f); err != nil {
		return err
	}
	idx := int(seq - rs.sendBase)
	rs.window[idx] = windowSlot{used: true, seq: seq, kind: f.Kind, f: f}
	rs.sendNext++
	return nil
}

// Flush sends every windowed frame (in sequence order), followed by a
// pure acknowledgement carrying the receiver's current delivered
// position, and flushes the wrapped session. Retransmission is a normal
// Flush: after a restart the window is reloaded from the replay log, so
// Flush resends every frame past the last acknowledged position; the
// receiver delivers each at most once.
func (rs *ReliableSession) Flush() error {
	rs.wmu.Lock()
	out := make([]Frame, 0, len(rs.window)+1)
	for i := range rs.window {
		sl := &rs.window[i]
		if !sl.used {
			continue
		}
		fr, err := rs.buildData(sl)
		if err != nil {
			rs.wmu.Unlock()
			return err
		}
		out = append(out, fr)
	}
	ack := rs.peekRecvBase()
	out = append(out, rs.buildAck(ack))
	rs.wmu.Unlock()

	for i := range out {
		if err := rs.sess.WriteFrame(out[i]); err != nil {
			return err
		}
	}
	return rs.sess.Flush()
}

// peekRecvBase reads the delivered position under the read lock so a
// Flush can acknowledge what the read side has handed out.
func (rs *ReliableSession) peekRecvBase() uint32 {
	rs.rmu.Lock()
	v := rs.recvBase
	rs.rmu.Unlock()
	return v
}

func (rs *ReliableSession) buildData(sl *windowSlot) (Frame, error) {
	e := envelope{
		seq:     sl.seq,
		ack:     rs.peekRecvBase(),
		typ:     envTypeData,
		flags:   sl.f.Flags,
		payload: sl.f.Payload,
	}
	// Encode the caller's Kind in the first payload-extension byte would
	// cost another field; instead the outer codec Kind carries it and
	// the envelope flags carry the caller flags.
	return encodeReliableFrame(e, sl.kind)
}

func (rs *ReliableSession) buildAck(ack uint32) Frame {
	b, _ := encodeEnvelope(envelope{
		seq: rs.sendNextLocked(),
		ack: ack,
		typ: envTypeAck,
	})
	return Frame{Flags: 0, Kind: kindAck, Payload: b}
}

func (rs *ReliableSession) sendNextLocked() uint32 {
	rs.wmu.Lock()
	v := rs.sendNext
	rs.wmu.Unlock()
	return v
}

// ReadFrame returns the next in-order caller frame, exactly once. It
// processes reliable messages internally: pure acknowledgements advance
// the send window (and checkpoint it), duplicates are re-acknowledged
// but not redelivered, and in-window out-of-order frames are held until
// the gap closes. A frame that predates the window or whose sequence
// lies more than one window width ahead is refused: delivery stops at
// the last in-order frame and the refusal becomes sticky.
func (rs *ReliableSession) ReadFrame() (ReliableFrame, error) {
	rs.rmu.Lock()
	defer rs.rmu.Unlock()

	if rs.rerr != nil {
		return ReliableFrame{}, rs.rerr
	}

	for {
		// Contiguous held frames are deliverable without another read.
		if f, ok := rs.held[rs.recvBase]; ok {
			delete(rs.held, rs.recvBase)
			rs.recvBase++
			return f, nil
		}

		outer, err := rs.sess.ReadFrame()
		if err != nil {
			// Under-layer problems (corrupt outer frame, truncation, EOF)
			// pass through with their established values; delivery state
			// is untouched so a reconnect on a new session is a separate
			// concern.
			return rs.failRead(err)
		}

		env, err := decodeEnvelope(outer.Payload)
		if err != nil {
			return rs.failRead(err)
		}

		// Every inbound message may carry a cumulative acknowledgement
		// for data we sent.
		if env.ack > 0 || true {
			rs.applyAck(env.ack)
		}

		if env.typ == envTypeAck || outer.Kind == kindAck {
			continue
		}
		if env.typ != envTypeData {
			// Unknown message types are treated like a corrupt envelope:
			// stopping is the only outcome that cannot lose ordering.
			return rs.failRead(ErrChecksum)
		}

		rf := ReliableFrame{Flags: env.flags, Kind: outer.Kind, Payload: env.payload}

		switch rs.classify(env.seq) {
		case seqOld:
			// Already delivered (a resend after its ack was lost). Do not
			// deliver again. The cumulative ack piggybacked on subsequent
			// outbound traffic (and the ack sent by the next Flush) tells
			// the peer to stop resending; just drop it.
			continue
		case seqInWindow:
			if _, dup := rs.held[env.seq]; dup {
				// Retransmission of a frame already held: keep the first
				// copy, deliver nothing twice.
				continue
			}
			rs.held[env.seq] = rf
			if env.seq == rs.recvBase {
				// Re-check contiguity from the top of the loop.
				continue
			}
			// Ahead of order: parked; send an immediate ack so the peer
			// learns the delivered position without waiting for a Flush.
			rs.sendAckLocked()
			continue
		case seqFuture:
			// Beyond one window width from the delivered position: refuse
			// and stop exactly where delivery currently is.
			return rs.failRead(fmt.Errorf("%w: sequence %d past window at %d", ErrChecksum, env.seq, rs.recvBase))
		}
	}
}

type seqClass int

const (
	seqOld seqClass = iota
	seqInWindow
	seqFuture
)

// classify decides where an inbound sequence stands relative to the
// receive window [recvBase, recvBase+Window).
func (rs *ReliableSession) classify(seq uint32) seqClass {
	if seq < rs.recvBase {
		return seqOld
	}
	if seq-rs.recvBase >= uint32(rs.cfg.Window) {
		return seqFuture
	}
	return seqInWindow
}

// sendAckLocked emits a standalone acknowledgement without disturbing
// the caller's read loop. Caller holds rmu; the send path takes wmu,
// which never nests in the opposite order (Flush takes wmu then
// peekRecvBase's rmu only after releasing wmu per call), so no deadlock.
func (rs *ReliableSession) sendAckLocked() {
	ackFrame := rs.buildAck(rs.recvBase)
	// Best effort: an unsent ack is retried by the next data exchange.
	_ = rs.sess.WriteFrame(ackFrame)
	_ = rs.sess.Flush()
}

// applyAck advances the send window past a cumulative acknowledgement
// and durably records the new acknowledged position.
func (rs *ReliableSession) applyAck(ack uint32) {
	rs.wmu.Lock()
	defer rs.wmu.Unlock()

	// ack is the highest delivered sequence; positions <= ack are done.
	// Ignore acknowledgements that do not move the window forward or
	// that lie beyond anything we numbered (a stale/foreign value).
	if ack == 0 {
		return
	}
	newBase := ack + 1
	if newBase <= rs.sendBase || ack >= rs.sendNext && rs.sendNext > rs.sendBase || ack >= rs.sendNext {
		// The compound condition reduces to: never pass sendNext.
		if ack >= rs.sendNext {
			return
		}
	}
	if newBase <= rs.sendBase {
		return
	}
	shift := newBase - rs.sendBase
	if shift > uint32(len(rs.window)) {
		shift = uint32(len(rs.window))
		newBase = rs.sendBase + shift
	}

	old := rs.window
	for i := 0; i < len(rs.window); i++ {
		if int(shift)+i < len(old) {
			rs.window[i] = old[int(shift)+i]
		} else {
			rs.window[i] = windowSlot{}
		}
	}
	rs.sendBase = newBase

	// Drop journaled frames that are now acknowledged, then make the new
	// position durable. The checkpoint write is best-effort inside
	// applyAck: a failure leaves the older complete checkpoint valid, and
	// recovery simply resends a few already-seen frames (deduped).
	if rs.log != nil {
		_ = rs.log.prefix(newBase)
	}
	_ = saveCheckpoint(rs.cfg.StateDir, ack)
}

// failRead records the terminal read-side result.
func (rs *ReliableSession) failRead(err error) (ReliableFrame, error) {
	rs.rerr = err
	return ReliableFrame{}, err
}

// Close checkpoints the final state and releases backing files. Pending
// unacknowledged frames remain in the replay log for a later restart to
// resend.
func (rs *ReliableSession) Close() error {
	rs.wmu.Lock()
	rs.closed = true
	rs.wmu.Unlock()
	if rs.log != nil {
		return rs.log.close()
	}
	return nil
}

// kindAck marks the outer codec Kind of pure acknowledgement frames.
// Data frames use the caller's Kind (0..254); 255 is reserved here.
const kindAck uint8 = 255

// ----------------------------------------------------------------------
// Durable state: a dual-record checkpoint file and a CRC'd replay log.
// ----------------------------------------------------------------------
//
// Checkpoint file layout: two fixed records, newest first is not assumed
// - each record is independently checksummed (CRC32) and stamped with a
// monotonically increasing generation. On load, the record with the
// highest generation that validates wins; a torn record (partial write
// caught mid-crash, or a flipped bit) fails its CRC and is ignored, so
// recovery always falls back to the previous complete checkpoint.
const (
	checkpointName = "reliable.ckp"
	cpRecordSize   = 4 + 4 + 4 // generation + ack + crc
	cpRecordCount  = 2
	checkpointSize = cpRecordSize * cpRecordCount
)

type cpRecord struct {
	generation uint32
	ack        uint32
}

func checkpointPath(dir string) string {
	return filepath.Join(dir, checkpointName)
}

func marshalCPRecord(r cpRecord) []byte {
	b := make([]byte, cpRecordSize)
	binary.BigEndian.PutUint32(b[0:4], r.generation)
	binary.BigEndian.PutUint32(b[4:8], r.ack)
	sum := crc32.ChecksumIEEE(b[0:8])
	binary.BigEndian.PutUint32(b[8:12], sum)
	return b
}

func unmarshalCPRecord(b []byte) (cpRecord, bool) {
	var r cpRecord
	if len(b) < cpRecordSize {
		return r, false
	}
	want := binary.BigEndian.Uint32(b[8:12])
	if crc32.ChecksumIEEE(b[0:8]) != want {
		return r, false
	}
	r.generation = binary.BigEndian.Uint32(b[0:4])
	r.ack = binary.BigEndian.Uint32(b[4:8])
	return r, true
}

// loadCheckpoint returns the newest valid record's acknowledged
// sequence. A file that is missing or empty means "no checkpoint". A
// file that is present but contains no valid record is a hard error
// (storage corruption, not a torn append): callers cannot safely tell
// which frames were acknowledged.
func loadCheckpoint(dir string) (uint32, bool, error) {
	data, err := os.ReadFile(checkpointPath(dir))
	if err != nil {
		if os.IsNotExist(err) {
			return 0, false, nil
		}
		return 0, false, err
	}
	if len(data) == 0 {
		return 0, false, nil
	}

	var best cpRecord
	found := false
	// Records beyond the expected two imply garbage; still only trust
	// validating records.
	for off := 0; off+cpRecordSize <= len(data); off += cpRecordSize {
		if r, ok := unmarshalCPRecord(data[off : off+cpRecordSize]); ok {
			if !found || r.generation > best.generation ||
				(r.generation == best.generation && r.ack > best.ack) {
				best = r
				found = true
			}
		}
	}
	if !found {
		return 0, false, fmt.Errorf("codec: checkpoint %s unreadable: %w", checkpointName, ErrChecksum)
	}
	return best.ack, true, nil
}

// nextCPGeneration inspects the file to choose the slot and generation
// for the next write.
func nextCPGeneration(dir string) (slot int, generation uint32, err error) {
	data, rerr := os.ReadFile(checkpointPath(dir))
	if rerr != nil && !os.IsNotExist(rerr) {
		return 0, 0, rerr
	}
	gen0, gen1 := uint32(0), uint32(0)
	ok0, ok1 := false, false
	if len(data) >= cpRecordSize {
		if r, ok := unmarshalCPRecord(data[0:cpRecordSize]); ok {
			gen0, ok0 = r.generation, true
		}
	}
	if len(data) >= checkpointSize {
		if r, ok := unmarshalCPRecord(data[cpRecordSize:checkpointSize]); ok {
			gen1, ok1 = r.generation, true
		}
	}
	switch {
	case !ok0 && !ok1:
		return 0, 1, nil
	case ok0 && (!ok1 || gen0 >= gen1):
		// Slot 0 holds the newest (or only) record; overwrite slot 1.
		return 1, gen0 + 1, nil
	default:
		// Slot 1 holds the newest; overwrite slot 0.
		return 0, gen1 + 1, nil
	}
}

// saveCheckpoint writes one new record into the alternate slot and then
// pads the file back to two slots, so at every durable instant at least
// the previous complete record is intact.
func saveCheckpoint(dir string, ack uint32) error {
	slot, generation, err := nextCPGeneration(dir)
	if err != nil {
		return err
	}
	rec := marshalCPRecord(cpRecord{generation: generation, ack: ack})

	path := checkpointPath(dir)
	f, err := os.OpenFile(path, os.O_RDWR|os.O_CREATE, 0o644)
	if err != nil {
		return err
	}
	defer f.Close()

	off := int64(slot * cpRecordSize)
	if _, err := f.WriteAt(rec, off); err != nil {
		return err
	}
	if err := f.Sync(); err != nil {
		return err
	}
	// Keep the file at exactly two records so slot math stays valid
	// after the very first write (which lands in slot 0).
	if slot == 0 {
		zero := make([]byte, cpRecordSize)
		if _, err := f.WriteAt(zero, int64(cpRecordSize)); err != nil {
			return err
		}
		if err := f.Sync(); err != nil {
			return err
		}
	}
	return nil
}

// ----------------------------------------------------------------------
// Replay log: length-prefixed, CRC'd records appended in sequence order.
// ----------------------------------------------------------------------
//
// Record layout:
//
//	+-----------+----------+---------+--------+----------+=========+
//	| seq (4)   | kind (1) | flags(2)| len(4) | crc32(4) | payload |
//	+-----------+----------+---------+--------+----------+=========+
//
// The CRC covers the 15 header bytes and the payload. On load the log is
// scanned front to back; a truncated final record (crash mid-append) is
// ignored as the incomplete tail, while a CRC mismatch anywhere earlier
// or a flipped bit in a complete record is ErrChecksum: the stream
// cannot be replayed faithfully, so callers must stop rather than
// delivering unverified bytes.
const (
	logName    = "reliable.log"
	logHdrSize = 4 + 1 + 2 + 4 + 4
)

type logRecord struct {
	seq  uint32
	kind uint8
	f    ReliableFrame
}

type replayLog struct {
	path string
	mu   sync.Mutex
	// records holds the complete, validated tail of the log.
	records []logRecord
}

func openReplayLog(dir string) (*replayLog, error) {
	l := &replayLog{path: filepath.Join(dir, logName)}
	if err := l.load(); err != nil {
		return nil, err
	}
	return l, nil
}

func (l *replayLog) load() error {
	data, err := os.ReadFile(l.path)
	if err != nil {
		if os.IsNotExist(err) {
			return nil
		}
		return err
	}

	off := 0
	for off < len(data) {
		if len(data)-off < logHdrSize {
			// Incomplete trailing header: a crash while appending. It is
			// the only truncation tolerated, and only at the very tail.
			break
		}
		hdr := data[off : off+logHdrSize]
		seq := binary.BigEndian.Uint32(hdr[0:4])
		kind := hdr[4]
		flags := binary.BigEndian.Uint16(hdr[5:7])
		plen := int(binary.BigEndian.Uint32(hdr[7:11]))
		wantCRC := binary.BigEndian.Uint32(hdr[11:15])

		end := off + logHdrSize + plen
		if end > len(data) {
			// Declared payload runs past EOF: incomplete tail record.
			break
		}
		h := crc32.NewIEEE()
		h.Write(hdr[:11])
		h.Write(data[off+logHdrSize : end])
		if h.Sum32() != wantCRC {
			return fmt.Errorf("codec: replay log %s corrupted: %w", logName, ErrChecksum)
		}

		payload := make([]byte, plen)
		copy(payload, data[off+logHdrSize:end])
		l.records = append(l.records, logRecord{
			seq:  seq,
			kind: kind,
			f:    ReliableFrame{Flags: flags, Kind: kind, Payload: payload},
		})
		off = end
	}
	return nil
}

// append journals one frame. Writes go through one file handle opened
// for append; the record is fully on disk before the frame is windowed.
func (l *replayLog) append(seq uint32, f ReliableFrame) error {
	l.mu.Lock()
	defer l.mu.Unlock()

	hdr := make([]byte, logHdrSize)
	binary.BigEndian.PutUint32(hdr[0:4], seq)
	hdr[4] = f.Kind
	binary.BigEndian.PutUint16(hdr[5:7], f.Flags)
	binary.BigEndian.PutUint32(hdr[7:11], uint32(len(f.Payload)))
	h := crc32.NewIEEE()
	h.Write(hdr[:11])
	h.Write(f.Payload)
	binary.BigEndian.PutUint32(hdr[11:15], h.Sum32())

	file, err := os.OpenFile(l.path, os.O_WRONLY|os.O_CREATE|os.O_APPEND, 0o644)
	if err != nil {
		return err
	}
	if _, err := file.Write(hdr); err != nil {
		file.Close()
		return err
	}
	if len(f.Payload) > 0 {
		if _, err := file.Write(f.Payload); err != nil {
			file.Close()
			return err
		}
	}
	if err := file.Sync(); err != nil {
		file.Close()
		return err
	}
	if err := file.Close(); err != nil {
		return err
	}

	l.records = append(l.records, logRecord{seq: seq, kind: f.Kind, f: f})
	return nil
}

// bounds reports the lowest and highest sequence held in the log.
func (l *replayLog) bounds() (base, next uint32, err error) {
	l.mu.Lock()
	defer l.mu.Unlock()
	if len(l.records) == 0 {
		return 0, 0, nil
	}
	return l.records[0].seq, l.records[len(l.records)-1].seq + 1, nil
}

// framesFrom returns the logged frames with sequence >= from, in order.
func (l *replayLog) framesFrom(from uint32) []logRecord {
	l.mu.Lock()
	defer l.mu.Unlock()
	var out []logRecord
	for _, r := range l.records {
		if r.seq >= from {
			out = append(out, r)
		}
	}
	return out
}

// prefix discards logged frames with sequence < base (already
// acknowledged), rewriting the log atomically via a temp file + rename.
func (l *replayLog) prefix(base uint32) error {
	l.mu.Lock()
	defer l.mu.Unlock()

	keep := l.records[:0]
	for _, r := range l.records {
		if r.seq >= base {
			keep = append(keep, r)
		}
	}
	if len(keep) == len(l.records) {
		return nil
	}
	l.records = keep

	tmp := l.path + ".tmp"
	f, err := os.OpenFile(tmp, os.O_WRONLY|os.O_CREATE|os.O_TRUNC, 0o644)
	if err != nil {
		return err
	}
	for _, r := range keep {
		hdr := make([]byte, logHdrSize)
		binary.BigEndian.PutUint32(hdr[0:4], r.seq)
		hdr[4] = r.kind
		binary.BigEndian.PutUint16(hdr[5:7], r.f.Flags)
		binary.BigEndian.PutUint32(hdr[7:11], uint32(len(r.f.Payload)))
		h := crc32.NewIEEE()
		h.Write(hdr[:11])
		h.Write(r.f.Payload)
		binary.BigEndian.PutUint32(hdr[11:15], h.Sum32())
		if _, err := f.Write(hdr); err != nil {
			f.Close()
			return err
		}
		if _, err := f.Write(r.f.Payload); err != nil {
			f.Close()
			return err
		}
	}
	if err := f.Sync(); err != nil {
		f.Close()
		return err
	}
	if err := f.Close(); err != nil {
		return err
	}
	return os.Rename(tmp, l.path)
}

func (l *replayLog) close() error {
	l.mu.Lock()
	defer l.mu.Unlock()
	return nil
}

