// saveCheckpoint writes one new record into the alternate slot. The
// other slot is untouched, so at every durable instant at least the
// previous complete record survives.
func saveCheckpoint(dir string, ack uint32) error {
	slot, generation, err := nextCPSlot(dir)
	if err != nil {
		return err
	}
	f, err := os.OpenFile(checkpointPath(dir), os.O_RDWR|os.O_CREATE, 0o644)
	if err != nil {
		return err
	}
	defer f.Close()

	if _, err := f.WriteAt(marshalCPRecord(cpRecord{generation: generation, ack: ack}),
		int64(slot*cpRecordSize)); err != nil {
		return err
	}
	if err := f.Sync(); err != nil {
		return err
	}
	// The first write lands in slot 0; size the file to both slots so a
	// later reader's slot math is valid (all-zero slot fails validation).
	if slot == 0 {
		if _, err := f.WriteAt(make([]byte, cpRecordSize), int64(cpRecordSize)); err != nil {
			return err
		}
		if err := f.Sync(); err != nil {
			return err
		}
	}
	return nil
}

